+    <header class="mx-auto max-w-3xl px-6 pt-14 pb-6">
+        @if (home is not null)
+        {
+            <a href="@home.Url()" class="text-sm font-semibold text-indigo-600 hover:text-indigo-500">&larr; All posts</a>
