+@inherits UmbracoViewPage<BlogPost>
+@{
+    Layout = "_Layout";
+    var home = Model.AncestorOrSelf<BlogHome>();
+}
+<article>
+    <header class="mx-auto max-w-3xl px-6 pt-14 pb-6">
+        @if (home is not null)
+        {
+            <a href="@home.Url()" class="text-sm font-semibold text-indigo-600 hover:text-indigo-500">&larr; All posts</a>
+        }
+        <h1 class="mt-4 text-4xl font-bold tracking-tight text-slate-900 sm:text-5xl">@Model.Name</h1>
+        <p class="mt-4 text-sm text-slate-500">
+            <time datetime="@Model.PublishDate.ToString("yyyy-MM-dd")">@Model.PublishDate.ToString("d MMMM yyyy")</time>
+            @if (!string.IsNullOrEmpty(Model.Author))
+            {
+                <span> &middot; by @Model.Author</span>
+            }
+        </p>
+        <p class="mt-6 text-xl leading-8 text-slate-600">@Model.Summary</p>
+    </header>
+
+    @{
+        var heroUrl = Model.Thumbnail?.GetCropUrl(width: 1400, height: 600);
+    }
+    @if (!string.IsNullOrEmpty(heroUrl))
+    {
+        <div class="mx-auto max-w-4xl px-6 pb-6">
+            <img src="@heroUrl" alt="" class="w-full rounded-xl object-cover shadow-lg" />
+        </div>
+    }
+
+    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
+</article>
+<div class="pb-16"></div>

